import{_ as s,c as e,o as a,a4 as i}from"./chunks/framework.CRCV4hx_.js";const u=JSON.parse('{"title":"Installation","description":"","frontmatter":{},"headers":[],"relativePath":"installation.md","filePath":"installation.md"}'),t={name:"installation.md"},n=i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>Here you can find the installation and first-time setup instructions for Resrv.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Statamic Resrv v6 requires <strong>PHP 8.4+</strong>, <strong>Laravel 12 or 13</strong>, <strong>Statamic 6</strong>, and <strong>Livewire 3.6.4+ or 4</strong>.</p><p>A database is required. You can use SQLite for development and for production if you expect to have a low number of concurrent users. MySQL is recommended for production in most cases. Laravel 12 and 13 ship with SQLite support out of the box.</p><div class="tip custom-block"><p class="custom-block-title">Upgrading from v5?</p><p>If you have an existing v5 site, follow the <a href="./upgrading">Upgrading to v6</a> guide instead. This page covers fresh installs only.</p></div><h2 id="composer" tabindex="-1">Composer <a class="header-anchor" href="#composer" aria-label="Permalink to &quot;Composer&quot;">​</a></h2><p>Install the package using Composer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">composer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> require</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reachweb/statamic-resrv</span></span></code></pre></div><h2 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to &quot;Migration&quot;">​</a></h2><p>After you&#39;ve set up <a href="https://laravel.com/docs/12.x/database#configuration" target="_blank" rel="noreferrer">your database</a>, you need to run the migrations to create the tables:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> migrate</span></span></code></pre></div><h2 id="install-script" tabindex="-1">Install script <a class="header-anchor" href="#install-script" aria-label="Permalink to &quot;Install script&quot;">​</a></h2><p>To complete the installation, run the install script:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> resrv:install</span></span></code></pre></div><p>The script asks five questions, each publishing a different set of assets:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Publish</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> the</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> developer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configuration</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> file</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (payment </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gateways</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Stripe</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> keys</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Most sites don</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;t need this. (yes/no) [no]:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &gt; no</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Do you want to publish the checkout form? (needed for Resrv to work correctly) (yes/no) [yes]:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &gt; yes</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Publishing checkout form</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Publishing checkout form blueprint</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Do you want to publish the Livewire views? (recommended) (yes/no) [yes]:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &gt; yes</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Publishing Livewire views</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Do you want to publish the language files? (needed only if you wish to edit them) (yes/no) [no]:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &gt; no</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Do you want to publish the email templates? (needed only if you wish to edit them) (yes/no) [no]:</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &gt; no</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Installation finished. Go get some reservations!</span></span></code></pre></div><p>Here&#39;s what each prompt does, and the recommended answer:</p><table tabindex="0"><thead><tr><th>Prompt</th><th>Default</th><th>Recommended</th><th>What it publishes</th></tr></thead><tbody><tr><td>Developer configuration file</td><td><code>no</code></td><td><code>no</code></td><td><code>config/resrv-config.php</code></td></tr><tr><td>Checkout form</td><td><code>yes</code></td><td><code>yes</code></td><td>The checkout form and blueprints</td></tr><tr><td>Livewire views</td><td><code>yes</code></td><td><code>yes</code></td><td>The frontend Livewire views, so you can customize them</td></tr><tr><td>Language files</td><td><code>no</code></td><td>Only if editing</td><td>Translation files under <code>lang/vendor/statamic-resrv</code></td></tr><tr><td>Email templates</td><td><code>no</code></td><td>Only if editing</td><td>Email views under <code>resources/views/vendor/statamic-resrv/email</code></td></tr></tbody></table><h3 id="the-developer-configuration-file" tabindex="-1">The developer configuration file <a class="header-anchor" href="#the-developer-configuration-file" aria-label="Permalink to &quot;The developer configuration file&quot;">​</a></h3><div class="info custom-block"><p class="custom-block-title">MOST SITES SKIP THIS</p><p>In v6, all user-facing settings (business information, reservation rules, currency, checkout, emails) are managed in the Control Panel under <strong>Resrv → Settings</strong> and stored on your site at <code>resources/addons/statamic-resrv.yaml</code>.</p></div><p>The published <code>config/resrv-config.php</code> only holds <strong>developer keys</strong>: <code>payment_gateway</code>, <code>payment_gateways</code>, the <code>stripe_*</code> env lookups, and the nested <code>checkout_forms</code> / <code>reservation_emails</code> override structures. Answer <strong>no</strong> to this prompt unless you need to register multiple <a href="./payment-gateways">payment gateways</a> or hand-edit <a href="./stripe">Stripe</a> keys in a file. You can publish it later at any time with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vendor:publish</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --tag=resrv-config</span></span></code></pre></div><p>See <a href="./configuration">Configuration</a> for the full settings model.</p><p>It is recommended to publish the checkout form and the Livewire views so you have total control over what Resrv displays.</p><h2 id="where-to-go-from-here" tabindex="-1">Where to go from here? <a class="header-anchor" href="#where-to-go-from-here" aria-label="Permalink to &quot;Where to go from here?&quot;">​</a></h2><p>We suggest you follow along the docs, starting with the <a href="./core-concepts">Core Concepts</a> to better understand how to use Resrv.</p>`,27),o=[n];function l(r,h,p,d,c,k){return a(),e("div",null,o)}const y=s(t,[["render",l]]);export{u as __pageData,y as default};
